<?php
namespace Tests\Feature\Adjustment;
use App\Models\{ChartOfAccount,Customer,CustomerLedger,DocumentSequence,GlBatch,User,Vendor,VendorLedger}; use App\Services\Adjustment\AdjustmentService; use App\Services\Ledger\GeneralLedgerService; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class FinancialReversalTest extends TestCase { use RefreshDatabase; private User $user; protected function setUp(): void {parent::setUp();$this->user=User::factory()->create();DocumentSequence::create(['code'=>'ADJ','prefix'=>'ADJ','date_format'=>'ymd','separator'=>'/','padding'=>4,'reset_period'=>'daily','is_active'=>true]);}
 public function test_customer_reversal_swaps_debit_and_credit(): void {$customer=Customer::create(['code'=>'C1','name'=>'Customer','credit_limit'=>0,'is_active'=>true]);$source=CustomerLedger::create(['posting_at'=>now(),'source_module'=>'TEST','document_type'=>'INV','document_number'=>'INV/1','customer_id'=>$customer->id,'debit'=>250,'credit'=>0,'posted_by'=>$this->user->id,'status'=>'POSTED']);$a=app(AdjustmentService::class)->reverse('customer',$source->id,'Reverse wrong customer invoice',$this->user);$r=CustomerLedger::findOrFail($a->reversal_entry_id);$this->assertSame(0.0,(float)$r->debit);$this->assertSame(250.0,(float)$r->credit);}
 public function test_vendor_reversal_swaps_debit_and_credit(): void {$vendor=Vendor::create(['code'=>'V1','name'=>'Vendor','is_active'=>true]);$source=VendorLedger::create(['posting_at'=>now(),'source_module'=>'TEST','document_type'=>'BILL','document_number'=>'BILL/1','vendor_id'=>$vendor->id,'debit'=>0,'credit'=>300,'posted_by'=>$this->user->id,'status'=>'POSTED']);$a=app(AdjustmentService::class)->reverse('vendor',$source->id,'Reverse wrong vendor bill posting',$this->user);$r=VendorLedger::findOrFail($a->reversal_entry_id);$this->assertSame(300.0,(float)$r->debit);$this->assertSame(0.0,(float)$r->credit);}
 public function test_gl_reversal_creates_balanced_opposite_batch(): void {$cash=ChartOfAccount::create(['code'=>'1000','name'=>'Cash','account_type'=>'ASSET','normal_balance'=>'DEBIT','allow_posting'=>true,'is_active'=>true]);$capital=ChartOfAccount::create(['code'=>'3000','name'=>'Capital','account_type'=>'EQUITY','normal_balance'=>'CREDIT','allow_posting'=>true,'is_active'=>true]);$batch=app(GeneralLedgerService::class)->postBatch(['document_number'=>'JV/100','posting_at'=>now(),'source_module'=>'TEST','document_type'=>'JV','posted_by'=>$this->user->id],[['account_id'=>$cash->id,'debit'=>500,'credit'=>0],['account_id'=>$capital->id,'debit'=>0,'credit'=>500]]);$a=app(AdjustmentService::class)->reverse('gl',$batch->id,'Reverse incorrect general journal',$this->user);$r=GlBatch::with('entries')->findOrFail($a->reversal_entry_id);$this->assertSame(500.0,(float)$r->entries->sum('debit'));$this->assertSame(500.0,(float)$r->entries->sum('credit'));$this->assertSame($batch->id,$r->reversal_of_id);}
}
